-- Update billing_audit_logs check constraint to include new audit types
-- TOKEN_FULFILLED and TOKEN_FULFILLMENT_FAILED were added to BillingAuditType enum

-- Drop the old constraint (generated by Hibernate ddl-auto)
ALTER TABLE billing_audit_logs DROP CONSTRAINT IF EXISTS billing_audit_logs_audit_type_check;

-- Re-create with all current enum values
ALTER TABLE billing_audit_logs ADD CONSTRAINT billing_audit_logs_audit_type_check
    CHECK (audit_type IN (
        'WEBHOOK_RECEIVED',
        'WEBHOOK_SUCCESS',
        'WEBHOOK_FAILED',
        'PAYMENT_COMPLETED',
        'PAYMENT_FAILED',
        'INVOICE_CANCELLED',
        'INVOICE_EXPIRED',
        'REFUND_INITIATED',
        'TOKEN_FULFILLED',
        'TOKEN_FULFILLMENT_FAILED'
    ));
